+    let output = run(
+        &["play"],
+        vec![
+            identity(),
+            (
+                "/remote/control",
+                json!({"ok":false,"message":"player unavailable"}),
+            ),
+        ],
+    );
+    assert!(!output.status.success());
+    assert!(String::from_utf8_lossy(&output.stderr).contains("player unavailable"));
+}
